# 长程 Agent 请求示例：把稳定内容放前面并显式打 Cache 断点
messages = [
    {
        "role": "system",
        "content": [
            {"type": "text", "text": SYSTEM_PROMPT},           # 固定不变的系统提示
            {"type": "text", "text": TOOL_DEFINITIONS_JSON,
             "cache_control": {"type": "ephemeral"}},          # 断点1：工具定义很少变化
        ],
    },
    {
        "role": "user",
        "content": [
            {"type": "text", "text": LONG_BACKGROUND_DOC,
             "cache_control": {"type": "ephemeral"}},          # 断点2：长背景文档整段复用
            {"type": "text", "text": f"当前时间：{now}\n用户问题：{query}"},  # 易变内容放最后，不打断点
        ],
    },
]
